using System.ComponentModel;
using ModelContextProtocol.Server;

public class MyTools
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add"), Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

using System.ComponentModel;
using ModelContextProtocol.Server;

public class MyResources
{
    /// <summary>
    /// A direct resource (fixed URI) that returns application configuration.
    /// </summary>
    [McpServerResource(Name = "config", UriTemplate = "config://app/settings",
        MimeType = "application/json"), Description("Returns application configuration data.")]
    public static string GetConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    /// <summary>
    /// A resource template — the {section} portion of the URI is bound to the parameter.
    /// </summary>
    [McpServerResource(Name = "config-section", UriTemplate = "config://app/{section}",
        MimeType = "application/json"), Description("Returns a specific configuration section.")]
    public static string GetConfigSection(string section)
    {
        var sections = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
        {
            ["database"] = new { Host = "localhost", Port = 5432, Name = "appdb" },
            ["logging"]  = new { Level = "Information", Format = "json" },
            ["cache"]    = new { Provider = "Redis", TtlMinutes = 60 },
        };

        if (!sections.TryGetValue(section, out var data))
        {
            return System.Text.Json.JsonSerializer.Serialize(new { Error = $"Unknown section: {section}" });
        }

        return System.Text.Json.JsonSerializer.Serialize(data, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

